{"op":"add","path":"/elements/rb-cmd","value":{"type":"Text","props":{"text":"kubectl config use-context production\nkubectl rollout undo deploy/app\nkubectl rollout status deploy/app --timeout=120s\nkubectl delete -f k8s/canary.yaml\ncurl -fsS https://example.com/healthz | jq .version   # expect the previous SHA","variant":"code"},"children":[]}}
