{"op":"add","path":"/elements/guide-header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["guide-title","guide-intro"]}}
{"op":"add","path":"/elements/guide-title","value":{"type":"Heading","props":{"text":"Production Deployment Guide","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/guide-intro","value":{"type":"Text","props":{"text":"A reliable deployment workflow for a typical Node.js web application. Complete each step in order: every stage reduces the chance of shipping broken, insecure, or unobservable software.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/prerequisites","value":{"type":"Alert","props":{"title":"Before you begin","message":"Make sure you have Node.js 20+, Git, Docker, and access to your production hosting account. Replace example values such as your-app and registry.example.com with your real project values.","type":"info"},"children":[]}}
{"op":"add","path":"/elements/step-list","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg","align":"stretch"},"children":["step-1","step-2","step-3","step-4","step-5","step-6","step-7"]}}
{"op":"add","path":"/elements/step-1","value":{"type":"Card","props":{"title":"1. Review the production configuration","description":"Confirm environment variables, service URLs, and production-only settings before building."},"children":["step-1-content"]}}
{"op":"add","path":"/elements/step-1-content","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["step-1-why","step-1-skip","step-1-command-label","step-1-command"]}}
{"op":"add","path":"/elements/step-1-why","value":{"type":"Text","props":{"text":"Why it matters: production configuration controls where your app connects, which credentials it uses, and how it behaves under real traffic. Reviewing it first prevents accidentally pointing production at a test database or enabling unsafe debug settings.","variant":"body"},"children":[]}}
{"op":"add","path":"/elements/step-1-skip","value":{"type":"Alert","props":{"title":"If you skip this","message":"Your release may fail at startup, expose detailed errors to users, connect to the wrong service, or lose access to required secrets.","type":"warning"},"children":[]}}
{"op":"add","path":"/elements/step-1-command-label","value":{"type":"Text","props":{"text":"Exact commands to run:","variant":"caption"},"children":[]}}
{"op":"add","path":"/elements/step-1-command","value":{"type":"Text","props":{"text":"cp .env.example .env.production\n# Edit .env.production and add production values\ncat .env.production","variant":"code"},"children":[]}}
{"op":"add","path":"/elements/step-2","value":{"type":"Card","props":{"title":"2. Install locked dependencies","description":"Install exactly the dependency versions recorded in the lockfile."},"children":["step-2-content"]}}
{"op":"add","path":"/elements/step-2-content","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["step-2-why","step-2-skip","step-2-command-label","step-2-command"]}}
{"op":"add","path":"/elements/step-2-why","value":{"type":"Text","props":{"text":"Why it matters: a clean, lockfile-based install makes your local build match CI and production. It catches missing or incompatible packages before you create a release artifact.","variant":"body"},"children":[]}}
{"op":"add","path":"/elements/step-2-skip","value":{"type":"Alert","props":{"title":"If you skip this","message":"Different machines can resolve different package versions, causing a build that works locally but fails in CI or after deployment.","type":"warning"},"children":[]}}
{"op":"add","path":"/elements/step-2-command-label","value":{"type":"Text","props":{"text":"Exact command to run:","variant":"caption"},"children":[]}}
{"op":"add","path":"/elements/step-2-command","value":{"type":"Text","props":{"text":"npm ci","variant":"code"},"children":[]}}
{"op":"add","path":"/elements/step-3","value":{"type":"Card","props":{"title":"3. Run automated quality checks","description":"Verify formatting, lint rules, unit tests, and type checks before creating a deployable build."},"children":["step-3-content"]}}
